# generated by darshan-singh-meel-knowledge-graph
"""Incremental graph update. From the repo root:
  python -I update.py [repo] [--dry-run | --status | --choice now|next|done|skip | --redo | --all | --docs later|no|done [doc ...]]
Finds the graph (.knowledge-graph pointer or <repo>-knowledge-graph/) and the change set since meta.json (working tree
vs meta.commit + untracked files; file hashes without git). Remaps path:line refs of changed files in the hand-written
_scripts inputs and the pages, re-extracts with _scripts/extract.py, merges only what the changed files own (unchanged
lines stay byte-identical), updates meta.json, runs _scripts/validate.py, writes _update/worklist.json.
Extractor contract: extract.py <repo> <out> [--files-from <list>] writes <out>/graph/{nodes,edges}.jsonl and skips
hand-written meaning entries whose ids are gone. --files-from: those files' nodes, the folders they add, edges from or
to them, and the meaning citing them. Without it: full run, only owned nodes and edges merged.
--dry-run: change set + say (ask | note | none). --status: the staleness line (empty when current).
--choice: answer to the graph question. --redo: rerun the last update from _update/prev after fixing _scripts inputs.
--docs: answer to the docs question (later | no), or done after a docs refresh (all pending docs, or only those named)."""
import difflib, hashlib, json, os, re, shutil, subprocess, sys, tempfile, time
from pathlib import Path

SKIP = {".git", "node_modules", "__pycache__", ".venv", "venv", "dist", "build", "generated-docs", "reviews", "analysis"}
SECRET = re.compile(r"(^|/)(\.env[^/]*|[^/]*\.(pem|key|p12|pfx|jks|keystore)|id_[^/]*|credentials[^/]*|secrets[^/]*|[^/]*\.tfvars"
                    r"|[^/]*\.tfstate[^/]*|\.npmrc|\.pypirc|\.netrc|\.git-credentials|kubeconfig|profiles\.yml"
                    r"|[^/]*service-account[^/]*\.json|\.docker/config\.json)$", re.I)
STRUCT = {"repo", "folder", "file"}
MEANING = {"flow", "business_rule", "process", "document", "test_case"}
PAGED = MEANING | {"folder", "module"}
PAGES = ("modules", "flows", "logic", "processes", "documents", "data")
INPUTS = {".json", ".jsonl", ".yml", ".yaml", ".md", ".txt", ".csv"}
TEXT = {".md", ".rst", ".txt", ".toml", ".cfg", ".ini", ".yml", ".yaml", ".json"}
CHOICES, DOCS = ("now", "next", "done", "skip"), ("later", "no", "done")
MARKER = ".generated-by-darshan-singh-meel-docs"
TAGGED = re.compile(r'name="generator" content="darshan-singh-meel-docs|generated by darshan-singh-meel-docs')


def git(root, *a):
    r = subprocess.run(["git", "-c", "core.quotepath=off", *a], cwd=root, capture_output=True, text=True, encoding="utf-8", errors="replace")
    return r.stdout if r.returncode == 0 else None


def read(p):
    return Path(p).read_text(encoding="utf-8", errors="replace")


def save(p, data):
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(data if isinstance(data, str) else json.dumps(data, indent=1, ensure_ascii=False), encoding="utf-8")


def find_graph(root):
    p = root / ".knowledge-graph"
    g = (root / p.read_text().strip()) if p.is_file() else root / f"{root.name}-knowledge-graph"
    if not (g / "meta.json").is_file():
        sys.exit(f"no graph found for {root.name}: build it first")
    return g.resolve()


def fhash(root, f, n):
    p = root / f
    return hashlib.sha256(p.read_bytes()).hexdigest()[:n] if p.is_file() else None


def walk(root, graph):
    out = []
    for d, dirs, files in os.walk(root):
        dirs[:] = [x for x in dirs if x not in SKIP and not x.startswith(".") and not x.endswith(("-knowledge-graph", "-graphs"))
                   and Path(d, x).resolve() != graph]
        out += [Path(d, x).relative_to(root).as_posix() for x in files]
    return out


def behind(root, a, b="HEAD"):
    """Commits a..b that touch files the graph maps (generated, review and skipped folders excluded)."""
    r = git(root, "rev-list", "--count", f"{a}..{b}", "--", ".", *(f":(exclude,glob)**/{d}/**" for d in SKIP)) if a and b else None
    return int(r) if r else -1


def change_set(root, graph, meta, all_files):
    """-> (modified, added, deleted, renames{old: new}, commits behind, head). Files already hashed in their current
    state are dropped, so uncommitted files are not reported again after an update."""
    hashes, base = meta.get("file_hashes", {}), meta.get("commit")
    n = len(next(iter(hashes.values()), "x" * 16))
    head = (git(root, "rev-parse", "HEAD") or "").strip() or None
    gp = graph.relative_to(root).as_posix() + "/" if graph.is_relative_to(root) else None
    keep = lambda f: f != ".knowledge-graph" and not (gp and f.startswith(gp)) and not SKIP & set(f.split("/")[:-1]) and not SECRET.search(f)
    mod, add, dele, ren = set(), set(), set(), {}
    if all_files:
        mod = {f for f in hashes if (root / f).is_file()}
    elif base and head and git(root, "cat-file", "-e", base) is not None:
        for line in git(root, "diff", "--name-status", "-M", base).splitlines():
            st, *p = line.split("\t")
            if st[0] == "R":
                ren[p[0]] = p[1]
            else:
                {"A": add, "D": dele}.get(st[0], mod).add(p[0])
        add |= set(git(root, "ls-files", "--others", "--exclude-standard").splitlines())
    elif hashes:
        cur = {f for f in (git(root, "ls-files", "-co", "--exclude-standard").splitlines() if head else walk(root, graph))
               if keep(f) and (root / f).is_file()}
        mod, add, dele = cur & set(hashes), cur - set(hashes), set(hashes) - cur
        for d in sorted(dele):  # no git: a delete and an add with the same content is a rename
            a = next((a for a in sorted(add) if fhash(root, a, n) == hashes[d]), None)
            if a:
                ren[d] = a
                add.discard(a)
                dele.discard(d)
    else:
        sys.exit("meta.json has no commit and no file_hashes: migrate the graph first (skill section 5, Migrate)")
    mod, add, dele = {f for f in mod if keep(f)}, {f for f in add if keep(f)}, {f for f in dele if keep(f)}
    ren = {o: nw for o, nw in ren.items() if keep(nw)}
    same = lambda f: f in hashes and fhash(root, f, n) == hashes[f]
    mod, add, dele = {f for f in mod if not same(f)}, {f for f in add if not same(f)}, {f for f in dele if f in hashes}
    ren = {o: nw for o, nw in ren.items() if o in hashes or not same(nw)}
    return mod, add, dele, ren, max(behind(root, base) if head else 0, 0), head


def doc_files(root, graph):
    """Generated docs: tagged files, or any file in a folder with the marker; _spec/ and inventories left out."""
    out = []
    for d in {root / "generated-docs", graph.parent / "generated-docs"}:
        for p in d.rglob("*") if d.is_dir() else []:
            if p.suffix in (".html", ".md", ".xhtml") and "_spec" not in p.parts and (
                    any((q / MARKER).exists() for q in p.parents if d in q.parents or q == d) or TAGGED.search(read(p)[:3000])):
                out.append(os.path.relpath(p, root).replace(os.sep, "/"))
    return sorted(out)


def status(root, graph, meta, nfiles, commits, head):
    c = lambda n, w="commit": f"{n} {w}{'s' * (n != 1)}"
    dp = meta.get("docs_pending") or {}
    if nfiles:
        g = f"Graph is {c(commits)} behind ({c(nfiles, 'file')})" if commits else \
            f"Graph is behind by {c(nfiles, 'uncommitted file' if head else 'changed file')}"
        if not (dp.get("docs") or doc_files(root, graph)):
            return g
        k = behind(root, dp["since"]) if dp.get("since") and head else commits
        return g + (f" · docs {c(k)} behind" if k > 0 else " · docs behind")
    if dp.get("docs"):
        k, d = behind(root, dp.get("since"), meta.get("commit")) if head else -1, c(len(dp["docs"]), "doc")
        return f"Docs are {c(k)} behind the graph ({d})" if k > 0 else f"Docs are behind the graph ({d}, {c(dp.get('updates', 1), 'graph update')})"
    return ""


def say(meta, nfiles, head, st):
    """ask = the graph question (and no note); note = the staleness line, no question."""
    p = meta.get("pending") or {}
    if not nfiles:
        return "note" if st else "none"
    if not p.get("choice") or p["choice"] == "next" and p.get("head", p.get("asked_head")) != head:
        return "ask"
    return "note"


def load(p):
    lines = read(p).splitlines() if p.is_file() else []
    return [(json.loads(l), l) for l in lines if l.strip()]


def line_map(a, b):
    """old line -> new line; lines inside a changed block map to the same offset, capped to the new block."""
    m = {}
    for tag, i1, i2, j1, j2 in difflib.SequenceMatcher(None, a, b, autojunk=False).get_opcodes():
        for k in range(i1, i2):
            m[k + 1] = j1 + 1 + (k - i1 if tag == "equal" else min(k - i1, max(j2 - j1 - 1, 0)))
    return m


def remap_refs(text, maps, ren):
    """Rewrite path:line and path:a-b refs of changed files to their new lines, and renamed paths -> (text, count)."""
    n = [0]

    def sub(m):
        p, lm = maps[m[1]]
        a = lm.get(int(m[2]), int(m[2]))
        s = f"{p}:{a}" + (f"-{max(lm.get(int(m[3]), int(m[3])), a)}" if m[3] else "")
        n[0] += s != m[0]
        return s
    if maps:
        rx = "|".join(map(re.escape, sorted(maps, key=len, reverse=True)))
        text = re.sub(rf"(?<![\w./-])({rx}):(\d+)(?:-(\d+))?(?!\d)", sub, text)
    for o, nw in ren.items():
        text, k = re.subn(rf"(?<![\w./-]){re.escape(o)}(?![\w/-])", nw, text)
        n[0] += k
    return text, n[0]


def scripts_hash(graph):
    h = hashlib.sha256()
    for p in sorted((graph / "_scripts").glob("*.py")):
        h.update(p.read_bytes())
    return h.hexdigest()[:16]


def main(argv):
    t0 = time.time()
    sys.stdout.reconfigure(encoding="utf-8")
    orig, choice, dchoice, dpaths = list(argv), None, None, []
    if "--docs" in argv:
        i = argv.index("--docs")
        dchoice, dpaths, argv = (argv[i + 1:i + 2] or [None])[0], argv[i + 2:], argv[:i]
    if "--choice" in argv:
        i = argv.index("--choice")
        choice = (argv[i + 1:i + 2] or [None])[0]
        del argv[i:i + 2]
    if "--choice" in orig and choice not in CHOICES or "--docs" in orig and dchoice not in DOCS:
        sys.exit(f"--choice takes {'|'.join(CHOICES)}; --docs takes {'|'.join(DOCS)} [doc ...]")
    args, flags = [a for a in argv if not a.startswith("--")], {a for a in argv if a.startswith("--")}
    root = Path(args[0] if args else ".").resolve()
    graph = find_graph(root)
    redo = "--redo" in flags
    src = graph / "_update/prev" if redo else graph
    if redo and not (src / "meta.json").is_file():
        sys.exit("nothing to redo: no _update/prev (it is written by an update)")
    meta = json.loads(read(src / "meta.json"))
    if choice or dchoice:
        meta = json.loads(read(graph / "meta.json"))
        if choice:
            meta["pending"] = {"choice": choice, "head": (git(root, "rev-parse", "HEAD") or "").strip() or None}
        elif dchoice == "done":
            left = [d for d in meta.get("docs_pending", {}).get("docs", [])
                    if dpaths and not any(d == p.rstrip("/") or d.startswith(p.rstrip("/") + "/") for p in dpaths)]
            meta.pop("docs_pending", None) if not left else meta["docs_pending"].update(docs=left)
        elif meta.get("docs_pending"):
            meta["docs_pending"]["choice"] = dchoice
        save(graph / "meta.json", meta)
        return print(f"recorded: {choice or 'docs ' + dchoice}")
    mod, add, dele, ren, commits, head = change_set(root, graph, meta, "--all" in flags)
    changed, gone = sorted(mod | add | set(ren.values())), sorted(dele | set(ren))
    nfiles = len(changed) + len(dele)
    st = status(root, graph, meta, nfiles, commits, head)
    if "--status" in flags:
        return print(st)
    sc = meta.get("scripts_hash") not in (None, scripts_hash(graph))
    if "--dry-run" in flags:
        return print(json.dumps({"commits_behind": commits, "files": nfiles, "modified": sorted(mod), "added": sorted(add),
                                 "deleted": sorted(dele), "renamed": ren, "uncommitted": bool(git(root, "status", "--porcelain")),
                                 "last_choice": (meta.get("pending") or {}).get("choice"), "say": say(meta, nfiles, head, st),
                                 "status": st, "scripts_changed": sc}, indent=1, ensure_ascii=False))
    if not nfiles:
        return print("graph is up to date (after fixing _scripts inputs: --redo)")
    base = meta.get("commit")
    own = set(changed) | set(gone)
    # without git the old text is unknown, except for a rename (same content by definition there)
    old_text = lambda f: git(root, "show", f"{base}:{f}") if base and head and f else         read(root / ren[f]) if f in ren and (root / ren[f]).is_file() else None
    maps = {}  # changed file -> (new path, old line -> new line)
    for o in sorted(mod) + sorted(ren):
        a, nw = old_text(o), ren.get(o, o)
        if a is not None and (root / nw).is_file():
            maps[o] = (nw, line_map(a.splitlines(), read(root / nw).splitlines()))
    tmp = Path(tempfile.mkdtemp())
    try:
        shutil.copytree(graph / "_scripts", tmp / "_scripts", ignore=shutil.ignore_patterns("__pycache__"))
        nref, inputs = 0, []
        for p in (tmp / "_scripts").rglob("*") if not redo else []:
            if p.suffix in INPUTS:
                t, k = remap_refs(read(p), maps, ren)
                if k:
                    save(p, t)
                    nref, inputs = nref + k, inputs + [p]
        ex = tmp / "_scripts/extract.py"
        if not ex.is_file():
            sys.exit("graph has no _scripts/extract.py: migrate it (skill section 5, Migrate)")
        s, lst = read(ex), tmp / "files.txt"
        save(lst, "\n".join(changed))
        mode = "--files-from" if "--files-from" in s else "--files" if "--files" in s else None
        by_files = bool(mode)
        # -E -s, not -I: the script folder stays on sys.path, so extract.py may import its siblings
        cmd = [sys.executable, "-E", "-s", str(ex), str(root), str(tmp)] + ([mode, str(lst)] if mode == "--files-from" else
                                                                            ["--files", *changed] if mode else [])
        r = subprocess.run(cmd, capture_output=True, text=True, encoding="utf-8", errors="replace")
        if r.returncode or not (tmp / "graph/nodes.jsonl").is_file():
            cited = sorted({f for f in gone for p in (tmp / "_scripts").rglob("*") if p.suffix in INPUTS and f in read(p)})
            sys.exit("extract.py failed" + ("" if r.returncode else ": no graph/nodes.jsonl (built before the update contract? "
                                            "skill section 5, Migrate)") + (f"\nnote: _scripts inputs cite removed files "
                     f"{', '.join(cited)}; the extractor must skip such entries (or drop them), then rerun" if cited else "") + f"\n{r.stderr[-2000:]}")
        work, line = merge(root, graph, src, tmp, meta, mod, add, dele, ren, own, changed, by_files, maps, old_text, head, redo, sc)
        work["remapped_refs"] = nref
        for p in inputs:  # remapped hand-written inputs replace the originals only after a good run
            shutil.copy(p, graph / p.relative_to(tmp))
    finally:
        shutil.rmtree(tmp, ignore_errors=True)
    save(graph / "_update/worklist.json", work)
    print(f"updated {commits} commits, {nfiles} files (~{len(mod)} +{len(add)} -{len(dele)} >{len(ren)}) | {line} | "
          f"refs remapped {work['remapped_refs'] + work['page_refs_remapped']} | {work['validate'][0]} | {time.time() - t0:.1f}s")


def merge(root, graph, src, tmp, meta, mod, add, dele, ren, own, changed, by_files, maps, old_text, head, redo, sc):
    def rp(s):  # old path -> new path inside ids and evidence, for renamed files
        for o, nw in ren.items():
            s = re.sub(rf"(^|:){re.escape(o)}(:|$)", lambda m: m[1] + nw + m[2], s)
        return s

    def remap(rows, keys):
        out = []
        for x, l in rows:
            y = {k: rp(v) if k in keys and isinstance(v, str) else v for k, v in x.items()}
            out.append((y, l if y == x else json.dumps(y, ensure_ascii=False)))
        return out

    evp = lambda s: re.sub(r":\d+(-\d+)?$", "", s if isinstance(s, str) else "")
    touch = lambda e, ids: e["from"] in ids or e["to"] in ids
    oldN, oldE = load(src / "graph/nodes.jsonl"), load(src / "graph/edges.jsonl")
    old = {n["id"]: (n, l) for n, l in oldN}
    newN = {n["id"]: (n, l) for n, l in remap(load(tmp / "graph/nodes.jsonl"), ("id", "path"))}
    newE, oldE2 = remap(load(tmp / "graph/edges.jsonl"), ("from", "to", "evidence")), remap(oldE, ("from", "to", "evidence"))
    # a flow, rule or process is owned when any of its steps or edges cites a changed or deleted file, not only its anchor
    typ = lambda i: (old.get(i) or newN.get(i) or ({},))[0].get("type")
    pid = {i for i, (n, _) in list(old.items()) + list(newN.items()) if n.get("path") in own}
    mown = {i for i, (n, _) in list(old.items()) + list(newN.items()) if n.get("type") in MEANING
            and any(isinstance(s, dict) and (evp(s.get("evidence")) in own or s.get("node") in pid) for s in n.get("steps") or [])}
    mown |= {x for e, _ in oldE + newE if evp(e.get("evidence")) in own for x in (e["from"], e["to"]) if typ(x) in MEANING}
    if redo:  # --redo also re-merges what the last worklist asked to fix, wherever it lives
        w = json.loads(read(graph / "_update/worklist.json")) if (graph / "_update/worklist.json").is_file() else {}
        mown |= {r["id"] for r in w.get("refresh", [])} | set(w.get("meaning", [])) | {s for s in w.get("summaries", []) if s in newN}
        # and every fix in the inputs: nodes added or edited, ends of added edges; full run: also what was taken out
        ek = lambda e: (e["from"], e["to"], e["type"], e.get("evidence"))
        ok, nk = {ek(e) for e, _ in oldE2}, {ek(e) for e, _ in newE}
        mown |= {i for i, (n, _) in newN.items() if i not in old or n != old[i][0]}
        mown |= {x for e, _ in newE if ek(e) not in ok for x in (e["from"], e["to"])}
        if not by_files:
            mown |= {i for i, (n, _) in old.items() if i not in newN and n.get("type") in MEANING}
            mown |= {x for e, _ in oldE2 if ek(e) not in nk for x in (e["from"], e["to"]) if x in newN}
    mown ={i for i in mown if not by_files or i in newN}
    # a folder is re-merged with its changed files; with --files-from the extractor returns new folders only
    owned = lambda n: n.get("path") in own or n["id"] in mown or (n.get("type") == "folder" and n.get("path") not in (None, "", ".")
                                                                  and any(f.startswith(n["path"] + "/") for f in own)
                                                                  and not (by_files and n["id"] in old))
    keepN = {i: v for i, v in old.items() if not owned(v[0])}
    for i, v in newN.items():
        if owned(v[0]):
            keepN[i] = old[i] if i in old and old[i][0] == v[0] else v
    left = {n.get("path") for n, _ in keepN.values() if n.get("type") not in ("folder", "repo")}
    keepN = {i: v for i, v in keepN.items() if v[0].get("type") != "folder" or v[0].get("path") in (None, "", ".")
             or any(f and f.startswith(v[0]["path"] + "/") for f in left)}
    ownedids = {i for i, (n, _) in list(old.items()) + list(newN.items()) if owned(n)}
    # --files-from returns edges from or to the changed files only: other edges of owned meaning stay as they were
    keepE = [(e, l) for e, l in oldE2 if evp(e.get("evidence")) not in own and not touch(e, pid if by_files else ownedids)]
    seen = {(e["from"], e["to"], e["type"], e.get("evidence")) for e, _ in keepE}
    for e, l in newE:
        k = (e["from"], e["to"], e["type"], e.get("evidence"))
        if k not in seen and (evp(e.get("evidence")) in own or touch(e, ownedids)):
            seen.add(k)
            keepE.append((e, l))
    dangling = [e for e, _ in keepE if e["from"] not in keepN or e["to"] not in keepN]
    keepE = [(e, l) for e, l in keepE if e["from"] in keepN and e["to"] in keepN]

    # changed = the node's own lines differ (lines of nodes nested inside it masked out), old text from git
    def spans(ns):
        d = {}
        for n in ns:
            if n.get("path") and n.get("line_start"):
                d.setdefault(n["path"], []).append((n["line_start"], n.get("line_end") or n["line_start"], n["id"]))
        return d

    def own_lines(n, sp, length):
        a, b = n.get("line_start") or 1, min(n.get("line_end") or length, length)
        inner = {k for s, e, i in sp.get(n.get("path"), []) if i != n["id"] and a <= s and e <= b and e - s < b - a for k in range(s, e + 1)}
        return [k for k in range(a, b + 1) if k not in inner]

    def code(text, n, sp):
        if text is None:
            return None
        ls = text.splitlines()
        return "\n".join(ls[k - 1].strip() for k in own_lines(n, sp, len(ls)))

    oldsp, newsp = spans(n for n, _ in oldN), spans(n for n, _ in keepN.values())
    newtext = {f: read(root / f) for f in changed if (root / f).is_file()}
    cache = {}
    alias = {rp(i): i for i in old if rp(i) != i}
    new_ids, chg_ids, moved = [], [], []
    pos = lambda n: f"{n.get('path') or n['id']}" + (f":{n['line_start']}-{n.get('line_end') or n['line_start']}" if n.get("line_start") else "")
    for i, (n, _) in keepN.items():
        oi = i if i in old else alias.get(i)
        if not owned(n) or n.get("type") in STRUCT and oi:
            continue
        if not oi:
            new_ids.append(i)
            continue
        on = old[oi][0]
        if n.get("path") not in own:  # owned through a step or edge only: its own code did not change
            continue
        p = on.get("path")
        if p not in cache:
            cache[p] = old_text(p)
        if cache[p] is None or code(cache[p], on, oldsp) != code(newtext.get(n.get("path")), n, newsp):
            chg_ids.append(i)
        elif pos(on) != pos(n):
            moved.append({"id": i, "was": pos(on), "at": pos(n)})
    removed = sorted(i for i in old if i not in keepN and i not in alias.values())
    hot = set(new_ids) | set(chg_ids) | set(removed)
    nb = {x for e, _ in oldE + keepE if e["type"] != "contains" and touch(e, set(chg_ids) | set(removed)) for x in (e["from"], e["to"])}
    nb = sorted(i for i in nb - hot if i in keepN and keepN[i][0].get("type") not in STRUCT)
    meaning = sorted(i for i in hot | set(nb) | mown if i in keepN and keepN[i][0].get("type") in MEANING)
    # what pages, docs and hand-written files to look at
    words = lambda s: {w.lower() for w in re.findall(r"[A-Z]?[a-z]+|[A-Z]+(?![a-z])", s or "") if len(w) >= 3}
    kept = {w for n, _ in keepN.values() for w in words(n.get("name")) | words(Path(n.get("path") or "").stem)}
    gone_names = {old[i][0].get("name") or "" for i in removed if old[i][0].get("type") not in STRUCT} | {Path(f).stem for f in dele}
    names = [n.get("name") for n, _ in keepN.values()]
    rx_of = lambda ws, f=0: re.compile(r"\b(" + "|".join(map(re.escape, sorted(ws))) + r")\b", f) if ws else None
    # removed words (any case) that no kept node uses, and removed names exactly as written
    rm_rx = rx_of({w for s in gone_names for w in words(s)} - kept, re.I)
    nm_rx = rx_of({s for s in gone_names if len(s) >= 4 and s not in names})
    # changed names, only those no other node shares (a project-wide name would hit every page)
    cn_rx = rx_of({n for n in (keepN[i][0].get("name") for i in chg_ids if keepN[i][0].get("type") not in STRUCT)
                   if n and len(n) >= 4 and names.count(n) == 1})
    found = lambda t, rs: sorted({m.lower() for r in rs if r for m in r.findall(t)})
    cites = set(hot) | add | dele | set(ren) | set(ren.values())
    for i in set(chg_ids) | set(removed):
        for x, sp, t in ((old.get(alias.get(i, i), ({},))[0], oldsp, cache.get(old.get(alias.get(i, i), ({},))[0].get("path"))),
                         (keepN.get(i, ({},))[0], newsp, newtext.get(keepN.get(i, ({},))[0].get("path")))):
            if x.get("path") and x.get("line_start"):
                cites |= {f"{x['path']}:{k}" for k in own_lines(x, sp, len(t.splitlines()) if t else x.get("line_end") or x["line_start"])}
    rx = re.compile("(" + "|".join(map(re.escape, sorted(cites, key=len, reverse=True))) + r")(?!\d)") if cites else None
    hit = lambda t: bool(rx and rx.search(t) or found(t, (rm_rx, nm_rx, cn_rx)))
    slug = lambda s: re.sub(r"[^a-z0-9]+", "-", (s or "").lower()).strip("-")
    sl = lambda n: {slug(n["id"].split(":", 1)[-1]), slug(n.get("name")), slug(n.get("path")) if n.get("type") in ("folder", "module") else ""} - {""}
    allp = sorted(p for d in PAGES for p in (graph / d).rglob("*") if p.is_file())
    keptsl = {s for n, _ in keepN.values() if n.get("type") in PAGED for s in sl(n)}
    gonesl = {s for i in removed if old[i][0].get("type") in PAGED for s in sl(old[i][0])} - keptsl
    parents = {slug(Path(f).parent.as_posix()) or "root" for f in add | dele | set(ren) | set(ren.values())}
    rel = lambda p: p.relative_to(graph).as_posix()
    pages_delete = [rel(p) for p in allp if slug(p.stem) in gonesl]
    page_text = {p: read(p) for p in allp + [graph / "index.md", graph / "README.md"] if p.is_file()}
    pages = sorted({rel(p) for p in allp if rel(p) not in pages_delete and (hit(page_text[p]) or slug(p.stem) in parents)})
    have = {slug(p.stem) for p in allp}
    pages_new = sorted(i for i in new_ids if keepN[i][0].get("type") in PAGED and not sl(keepN[i][0]) & have)
    summaries = sorted(i for i, (n, _) in keepN.items() if n.get("type") in ("repo", "folder") and (
        found(n.get("summary") or "", (rm_rx, nm_rx)) or slug(n.get("path")) in parents or n.get("path") in (None, "", ".") and (add or dele)))
    docs = [d for d in doc_files(root, graph) if hit(read(root / d))]
    hand = git(root, "ls-files").splitlines() if head else walk(root, graph)
    mentions = []
    for f in sorted(hand):
        p = root / f
        if f in own or SECRET.search(f) or SKIP & set(f.split("/")[:-1]) or not (p.suffix in TEXT or p.name.lower().startswith("readme")) \
                or not p.is_file() or p.stat().st_size > 1_000_000 or graph in p.resolve().parents:
            continue
        ws = found(read(p), (rm_rx, nm_rx, cn_rx))
        if ws:
            mentions.append({"file": f, "names": ws})
    # write: remapped pages, graph, meta; then validate
    nref = 0
    for p, t in page_text.items() if not redo else []:
        t2, k = remap_refs(t, maps, ren)
        if k:
            save(p, t2)
            nref += k
    if not redo:
        for name in ("graph/nodes.jsonl", "graph/edges.jsonl", "meta.json"):
            if (graph / name).is_file():
                (graph / "_update/prev" / name).parent.mkdir(parents=True, exist_ok=True)
                shutil.copy(graph / name, graph / "_update/prev" / name)
    save(graph / "graph/nodes.jsonl", "".join(l + "\n" for _, l in keepN.values()))
    save(graph / "graph/edges.jsonl", "".join(l + "\n" for _, l in keepE))
    if not by_files:
        for p in (tmp / "graph").iterdir():
            if p.name not in ("nodes.jsonl", "edges.jsonl") and p.is_file():
                shutil.copy(p, graph / "graph" / p.name)
    hashes = meta.get("file_hashes", {})
    n = len(next(iter(hashes.values()), "x" * 16))
    fh = {k: v for k, v in hashes.items() if k not in own} | {f: fhash(root, f, n) for f in changed if (root / f).is_file()}
    base = meta.get("commit")
    dp = meta.get("docs_pending") or {}
    new_docs = sorted(set(docs) - set(dp.get("docs", [])))
    if docs or dp:
        dp = {"since": dp.get("since", base), "docs": sorted(set(dp.get("docs", [])) | set(docs)), "updates": dp.get("updates", 0) + 1,
              "choice": None if new_docs else dp.get("choice")}
    meta.update(file_hashes=dict(sorted(fh.items())), commit=head or base, scripts_hash=scripts_hash(graph),
                updated=time.strftime("%Y-%m-%d %H:%M UTC", time.gmtime()))
    meta.pop("pending", None)
    meta.pop("docs_pending", None) if not dp else meta.update(docs_pending=dp)
    if "counts" in meta:
        cnt = lambda xs, k: dict(sorted({t: sum(1 for x in xs if x.get(k) == t) for t in {x.get(k) for x in xs}}.items()))
        NN, EE = [x for x, _ in keepN.values()], [e for e, _ in keepE]
        meta["counts"].update(files=sum(1 for x in NN if x.get("type") == "file") or len(left), nodes=len(NN), edges=len(EE),
                              nodes_by_type=cnt(NN, "type"), edges_by_type=cnt(EE, "type"), flows=sum(1 for x in NN if x.get("type") == "flow"))
    save(graph / "meta.json", meta)
    val = graph / "_scripts/validate.py"
    vr = subprocess.run([sys.executable, "-E", "-s", str(val), str(root), str(graph)], capture_output=True, text=True,
                        encoding="utf-8", errors="replace") if val.is_file() else None
    vout = (vr.stdout.strip().splitlines() or [f"validate.py failed: {vr.stderr.strip()[-300:]}"]) if vr else ["no validate.py (skill section 5, Migrate)"]
    why = [w for w, c in (("more than half the files changed", len(own) > (len(hashes) or 1) / 2), ("_scripts/*.py changed", sc)) if c]
    work = {"base": base, "head": head, "files": {"modified": sorted(mod), "added": sorted(add), "deleted": sorted(dele), "renamed": ren},
            "refresh": [{"id": i, "why": w, "at": pos(keepN[i][0])} | ({"was": pos(old[alias.get(i, i)][0])} if w == "changed" else {})
                        for w, ids in (("new", sorted(new_ids)), ("changed", sorted(chg_ids)), ("neighbour", nb)) for i in ids],
            "moved": moved, "renamed_ids": {o: i for i, o in alias.items() if i in keepN}, "removed": removed, "meaning": meaning,
            "summaries": summaries + ["index.md big picture"], "pages": pages + ["index.md"], "pages_new": pages_new,
            "pages_delete": pages_delete, "check_mentions": mentions, "docs": dp.get("docs", []), "docs_new": new_docs,
            "docs_ask": bool(dp.get("docs")) and (bool(new_docs) or dp.get("choice") in (None, "later")),
            "page_refs_remapped": nref, "dangling_edges_dropped": [f"{e['type']} {e['from']} -> {e['to']}" for e in dangling],
            "validate": vout, "full_rebuild_advised": bool(why), "full_rebuild_why": why}
    line = (f"nodes +{len(new_ids)} ~{len(chg_ids)} -{len(removed)} >{len(moved)} | worklist {len(work['refresh'])} nodes, "
            f"{len(meaning)} meaning, {len(pages) + 1} pages (+{len(pages_new)} -{len(pages_delete)}), {len(mentions)} mentions, "
            f"{len(work['docs'])} docs (ask {'yes' if work['docs_ask'] else 'no'})")
    return work, line


if __name__ == "__main__":
    main(sys.argv[1:])
